code='''from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(y+dy,x+dx)
                    if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==color:
                        seen.add(z); q.append(z)
            comps.append((color,cells))
    def canon(cells):
        forms=[]
        for swap in (False,True):
            for sy in (1,-1):
                for sx in (1,-1):
                    pts=[(sy*(x if swap else y),sx*(y if swap else x)) for y,x in cells]
                    my=min(y for y,x in pts); mx=min(x for y,x in pts)
                    forms.append(tuple(sorted((y-my,x-mx) for y,x in pts)))
        return min(forms)
    groups={}
    for color,cells in comps: groups.setdefault(canon(cells),[]).append((color,cells))
    out=[row[:] for row in grid]
    for items in groups.values():
        ones=[cells for color,cells in items if color==1]
        others=[color for color,cells in items if color!=1]
        if ones and others:
            for cells in ones:
                color=others[0]
                for r,c in cells: out[r][c]=color
    return out
'''
